// ===== L2338-L2360 renderPostsTable =====
function renderPostsTable(rows) {
  if (!rows.length) return `<div class="empty">暂无作品数据</div>`;
  const actionButtons = (item) => {
    const buttons = [
      `<button class="ghost js-edit-post" data-id="${item.id}">编辑</button>`,
      `<button class="ghost danger js-delete-post" data-id="${item.id}">删除</button>`
    ];
    return `<div class="actions">${buttons.join("")}</div>`;
  };
  return `
    <div class="table-wrap">
      <table>
        <thead>
          <tr><th>封面</th><th>标题</th><th>账号</th><th>员工</th><th>平台</th><th>类型</th><th>发布时间</th><th>点赞</th><th>评论</th><th>互动更新时间</th><th>链接</th><th>操作</th></tr>
        </thead>
        <tbody>
          ${rows.map((item) => `<tr><td>${item.coverImageUrl ? `<button class="image-trigger image-trigger-inline js-open-image" data-src="${item.coverImageUrl}" type="button"><img class="cover-thumb" src="${item.coverImageUrl}" alt="封面" loading="lazy" decoding="async" /></button>` : ""}</td><td>${item.title}</td><td>${item.accountName}</td><td>${item.employeeName}</td><td>${item.platform}</td><td>${item.postType}</td><td>${item.publishedAt}</td><td>${Number(item.likes || 0)}</td><td>${Number(item.comments || 0)}</td><td>${item.metricsUpdatedAt ? formatDate(item.metricsUpdatedAt) : "未抓取"}</td><td>${item.postUrl ? renderExternalLink(item.postUrl, "打开") : ""}</td><td>${actionButtons(item)}</td></tr>`).join("")}
        </tbody>
      </table>
    </div>
  `;
}


