  const coverPreviewUrl = state.postCoverPreviewUrl || (editing?.coverImageUrl || "");
  const coverPreviewLabel = state.postCoverPreviewUrl
    ? "当前待上传封面"
    : (editing?.coverImageUrl ? "当前封面" : "");
