// ===== L5446-L5453 deletePost =====
async function deletePost(id) {
  if (!window.confirm("确认删除该作品吗？")) return;
  await api(`/api/posts/${id}`, { method: "DELETE" });
  state.editingPostId = state.editingPostId === id ? "" : state.editingPostId;
  await loadData();
  renderApp();
}


// ===== L5474-L5562 submitPost / savePostSuggestion / refreshScopedMetrics / rollbackScopedMetrics =====
async function submitPost(event) {
  event.preventDefault();
  const form = event.currentTarget;
  if (state.postSubmitting || form.dataset.submitting === "1") return;
  state.postSubmitting = true;
  form.dataset.submitting = "1";
  const submitButton = form.querySelector('button[type="submit"]');
  const submitText = submitButton ? submitButton.textContent : "";
  if (submitButton) {
    submitButton.disabled = true;
    submitButton.textContent = "提交中…";
  }
  const formData = new FormData(form);
  const id = String(formData.get("id") || "");
  // 封面 input 已脱离 form，需手动从 state 取文件并 append
  if (state.postCoverFile) {
    formData.set("coverImage", state.postCoverFile, state.postCoverFile.name || "pasted-cover.png");
  }
  let result;
  try {
    result = await api(id ? `/api/posts/${id}` : "/api/posts", {
      method: id ? "PUT" : "POST",
      body: formData
    });
  } catch (error) {
    // 失败：保留所有已填字段 + 草稿，仅提示错误
    if (error?.status === 401 && !id && typeof savePostFormDraftNow === "function") {
      savePostFormDraftNow();
      setFlash("warn", "登录已失效", "已优先保存当前作品草稿，请重新登录后再提交。");
    } else {
      setFlash("warn", id ? "作品保存失败" : "作品提交失败", error?.message || "请稍后重试，已填写的内容已保留。");
    }
    if (submitButton) {
      submitButton.disabled = false;
      submitButton.textContent = submitText || (id ? "保存作品" : "提交作品");
    }
    form.dataset.submitting = "0";
    state.postSubmitting = false;
    return;
  }

  // 成功：清掉封面 state + sessionStorage 草稿 + reset 文本字段
  clearPendingPostCover();
  state.postCoverUploadError = "";
  clearPostFormDraftStorage();
  state.postFormDraftRestorePrompt = null;
  resetPostFormDraftContext();
  try { form.reset(); } catch (_err) {}
  // 编辑态下完成后退出编辑
  const wasEditing = Boolean(id);
  if (wasEditing) state.editingPostId = "";
  state.postSubmitting = false;
  form.dataset.submitting = "0";
  setFlash("success", wasEditing ? "作品已更新" : "作品已提交", "这条作品已经写入后台，主管端同步看板后会立刻看到。");
  // 局部刷新：拉一次数据后只重渲染当前页（不调 renderApp 整页流程之外的逻辑）
  // 注意：renderApp 是整体路由渲染函数，按需求禁止调用；这里改为只刷新数据 + 重渲染当前页面板
  await loadData();
  rerenderPostEntrySectionsAfterSubmit();
  if (result && result.metricsSyncError) {
    alert(`作品已保存，但互动数据暂未自动抓到：${result.metricsSyncError}`);
  }
}

// 提交成功后的局部刷新：只重渲染录入页的「今日录入记录」与表单区，避免全页 renderApp
function rerenderPostEntrySectionsAfterSubmit() {
  // 表单已 reset；如果存在封面上传/草稿提示区，重渲染表单面板让 state 同步
  const formPanel = document.querySelector(".panel.entry-panel.entry-panel-compact");
  if (formPanel) {
    const editing = state.posts.find((item) => item.id === state.editingPostId);
    formPanel.innerHTML = `
      <div class="staff-form-head">
        <h3>${editing ? "编辑作品" : "新增作品"}</h3>
        <span class="muted">提交后会立刻写入后台，主管端同步后马上能看到。</span>
      </div>
      ${renderPostForm(editing, { compact: true })}
    `;
  }
  const recordsGrid = document.querySelector(".staff-entry-records .staff-posts-grid");
  if (recordsGrid) {
    const todayRows = getTodayStaffPosts();
    recordsGrid.innerHTML = todayRows.length
      ? todayRows.map(renderStaffPostCard).join("")
      : renderEmptyState("今天还没有录入作品", "先选账号、填链接和作品类型，第一条录进去后这里就会出现作品卡片。");
  }
  // 仅在录入页存在表单/记录的情况下重新绑定事件；若没有匹配 DOM（例如 admin 在作品看板视图），
  // 退化为整页 renderApp 让 admin 看板拿到最新数据。
  if (formPanel || recordsGrid) {
    if (typeof bindViewEvents === "function") {
      try { bindViewEvents(); } catch (_err) {}
    }
  } else {
    renderApp();
  }
}

async function savePostSuggestion(id) {
  const input = document.querySelector(`.post-board-suggestion-input[data-id="${id}"]`);
  if (!input) return;
  await api(`/api/posts/${id}/supervisor-suggestion`, {
    method: "PUT",
    body: JSON.stringify({
      supervisorSuggestion: input.value || ""
    })
  });
  setFlash("success", "主管建议已保存", "员工端这条作品会同步显示这条建议。");
  await loadData();
  renderApp();
}

async function refreshScopedMetrics() {
  try {
    const result = await api("/api/dashboard/refresh-entered-data", { method: "POST" });
    setFlash("success", "看板数据已同步", `已按员工当前录入的数据同步作品 ${result.postCount} 条、客资 ${result.leadCount} 条。`);
    await loadData();
    renderApp();
  } catch (error) {
    alert(error.message);
  }
}

async function rollbackScopedMetrics() {
  const postIds = getScopedRefreshPostIds();
  if (!postIds.length) {
    alert("当前范围内没有可回退的作品。");
    return;
  }

  if (!state.rollbackSnapshotDate) {
    alert("请先选择一个回退日期。");
    return;
  }

  if (!window.confirm(`确认将当前范围内作品的互动数据回退到 ${state.rollbackSnapshotDate} 的快照吗？`)) {
    return;
  }

  const password = window.prompt("请输入当前账号密码后再执行回退：", "");
  if (password === null) {
    return;
  }
  if (!String(password).trim()) {
    alert("未输入密码，已取消回退。");
    return;
  }

  try {
    const result = await api("/api/posts/rollback-metrics", {
      method: "POST",
      body: JSON.stringify({
        postIds,
        snapshotDate: state.rollbackSnapshotDate,
        password: String(password)
      })
    });
    await loadData();
    renderApp();
    const failedCount = Array.isArray(result.failed) ? result.failed.length : 0;
    alert(`已按 ${result.snapshotDate} 快照回退，成功 ${result.restored} 条，跳过 ${result.skipped} 条，失败 ${failedCount} 条。`);
  } catch (error) {
    alert(error.message);
  }
}


// ===== A-FE-3a 单条作品指标刷新（点击「刷新指标」按钮） =====
async function handleRefreshPostMetricsClick(button) {
  const id = button?.dataset?.id;
  if (!id) return;
  const post = state.posts.find((item) => item.id === id);
  if (!post) {
    alert("找不到这条作品，可能已被删除。");
    return;
  }
  if (!post.postUrl) {
    alert("这条作品没有作品链接，无法抓取互动数据。");
    return;
  }
  if (button.disabled) return;
  button.disabled = true;
  const originalText = button.textContent;
  button.textContent = "刷新中…";
  try {
    await api(`/api/posts/${id}/fetch-metrics`, {
      method: "POST",
      body: JSON.stringify({ postUrl: post.postUrl })
    });
    setFlash("success", "互动数据已刷新", "已写入最新点赞、评论、收藏数据，并保存一份历史快照。");
    await loadData();
    renderApp();
  } catch (error) {
    alert(error?.message || "刷新失败，请稍后重试。");
    button.disabled = false;
    button.textContent = originalText;
  }
}

// ===== A-FE-3b 批量刷新当前筛选作品互动数据 =====
async function handleBatchRefreshFilteredPosts() {
  // 复用 renderPostsMonitor 的过滤+排序逻辑，拿到当前筛选下的作品
  const filteredRows = getFilteredPostsForMonitor();
  // 仅对有作品链接的子集发起刷新
  const eligible = filteredRows.filter((item) => item.postUrl);
  if (!eligible.length) {
    alert("当前筛选下没有可刷新的作品");
    return;
  }
  // 二次确认：提示条数 + 预估耗时（每条 5s）
  if (!window.confirm(`确认批量刷新 ${eligible.length} 条作品互动数据吗？预计耗时 ${eligible.length * 5} 秒`)) {
    return;
  }
  const button = document.getElementById("batchRefreshFilteredPostsBtn");
  const originalText = button ? button.textContent : "";
  if (button) {
    button.disabled = true;
    button.textContent = "刷新中…";
  }
  try {
    const result = await api("/api/posts/refresh-metrics", {
      method: "POST",
      body: JSON.stringify({ postIds: eligible.map((item) => item.id) })
    });
    const results = Array.isArray(result?.results) ? result.results : [];
    const total = results.length;
    const success = results.filter((entry) => entry && entry.success).length;
    const failed = results.filter((entry) => entry && !entry.success).map((entry) => ({
      id: entry.id,
      title: entry.title || state.posts.find((item) => item.id === entry.id)?.title || entry.id,
      message: entry.message || "抓取失败",
    }));
    state.postBatchRefreshFailures = failed;
    setFlash(failed.length ? "warn" : "success", "批量刷新完成", `已刷新 ${success}/${total} 条${failed.length ? `，失败 ${failed.length} 条，可查看明细并重试。` : ""}`);
  } catch (error) {
    alert(error?.message || "批量刷新失败，请稍后重试。");
  } finally {
    // 无论成功失败都拉一次最新数据并整页重渲染（renderApp 会重新执行 bindViewEvents）
    await loadData();
    renderApp();
  }
}


// ===== A-FE-2 #7 作品批量粘贴导入对话框 =====
